create function operations_private.hub_product_tag_metadata_update_v1(p_session_token text,p_tag_id uuid,p_name text,p_color text default null,p_expected_name text default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog set statement_timeout='30s' set lock_timeout='5s' as $$
declare actor jsonb; before_tag public.product_tags%rowtype; result public.product_tags%rowtype;
begin
 actor:=operations_private.require_operations_hub_operator_session(p_session_token);
 if p_tag_id is null or coalesce(length(btrim(p_name)),0) not between 1 and 200 or p_color is not null and p_color !~ '^#[0-9a-fA-F]{6}$' then raise exception '태그 이름/색상 오류';end if;
 perform pg_advisory_xact_lock(hashtextextended('hub-rule-registry',0));
 select * into before_tag from public.product_tags where tag_id=p_tag_id and is_active for update;
 if not found then raise exception '활성 태그를 찾지 못했습니다.';end if;
 if p_expected_name is not null and before_tag.tag_name is distinct from p_expected_name then raise exception '태그 이름이 외부에서 변경됐습니다. 다시 조회하세요.';end if;
 if exists(select 1 from public.product_tags where is_active and tag_id<>p_tag_id and lower(btrim(tag_name))=lower(btrim(p_name))) then raise exception '같은 이름의 활성 태그가 있습니다.';end if;
 if before_tag.tag_name=btrim(p_name) and (p_color is null or p_color=before_tag.tag_color) then return to_jsonb(before_tag);end if;
 update public.product_tags set tag_name=btrim(p_name),tag_color=coalesce(p_color,tag_color),updated_at=clock_timestamp() where tag_id=p_tag_id returning * into result;
 insert into operations_private.hub_rule_events(action,before_value,after_value,actor) values('tag_metadata_update',to_jsonb(before_tag),to_jsonb(result),actor->>'username');
 return to_jsonb(result);
end $$;

revoke all on function operations_private.hub_product_tag_metadata_update_v1(text,uuid,text,text,text) from public,anon,authenticated;
grant execute on function operations_private.hub_product_tag_metadata_update_v1(text,uuid,text,text,text) to anon,authenticated;
create or replace function public.hub_product_tag_metadata_update_v1(p_session_token text,p_tag_id uuid,p_name text,p_color text default null,p_expected_name text default null)
returns jsonb language sql security invoker set search_path=pg_catalog as $fn$
 select operations_private.hub_product_tag_metadata_update_v1(p_session_token,p_tag_id,p_name,p_color,p_expected_name)
$fn$;
